?><div class="page-heading"><div><span class="eyebrow">FLEXIBLE LESSONS. CLEAR PRICES.</span><h1>Lesson packages</h1><p>Manage the options shown on your sample booking page.</p></div><a class="button" href="?view=packages&amp;new=1#package-editor">Add package</a></div><div class="admin-packages"><?php foreach(q('SELECT * FROM booking_packages ORDER BY active DESC,sort_order,id')->fetchAll() as $p):?><article class="panel padded"><div class="package-top"><?=badge($p['active']?'active':'archived')?><span><?=e($p['lesson_count'])?> × <?=e($p['duration_minutes'])?> min</span></div><h2><?=e($p['name'])?></h2><p class="muted"><?=e($p['description'])?></p><strong class="package-amount"><?=money($p['total_cents'])?><small> total</small></strong><div class="package-controls"><a class="small-button" href="?view=packages&amp;edit=<?=(int)$p['id']?>#package-editor">Edit package</a><form method="post" data-confirm="Change this package’s visibility on the sample page?"><?=csrfField()?><input type="hidden" name="action" value="toggle-package"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="text-button"><?=$p['active']?'Archive':'Activate'?></button></form></div></article><?php endforeach;?></div><?php if($edit||isset($_GET['new'])||$action==='save-package'):?><section id="package-editor" class="panel padded editor"><h2><?=$edit?'Edit package':'New package'?></h2><form method="post" class="form-grid"><?=csrfField()?><input type="hidden" name="action" value="save-package"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="field full"><label for="p-name">Package name</label><input id="p-name" name="name" maxlength="120" required value="<?=e($edit['name']??'')?>"></div><div class="field full"><label for="p-desc">Short description</label><textarea id="p-desc" name="description" maxlength="400" rows="3"><?=e($edit['description']??'')?></textarea></div><div class="field"><label for="p-total">Total price ($)</label><input id="p-total" name=