<?php elseif($view==='activity'):?><div class="page-heading"><div><span class="eyebrow">A CLEAR RECORD OF CHANGES</span><h1>Activity log</h1><p>Booking, package, and admin actions. All dates in Melbourne time.</p></div></div><section class="panel"><?php $rows=q('SELECT a.*,u.name FROM booking_activity a LEFT JOIN booking_admins u ON u.id=a.admin_id ORDER BY a.id DESC LIMIT 200')->fetchAll();if(!$rows):emptyState('Nothing to show yet','Booking and admin changes will be recorded here.');else:?><div class="table-wrap"><table><thead><tr><th>When</th><th>Action</th><th>Record</th><th>By</th><th>Details</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(localDate($r['created_at']))?></td><td><?=e($r['action'])?></td><td><?=e($r['target'])?></td><td><?=e($r['name']?:'Website visitor')?></td><td><?=e($r['detail'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;
pageEnd(true);
